export const meta = {
  "slug": "iphone",
  "name": "iPhone",
  "family": "Media",
  "collection": "Media",
  "component": "createLinearIphone"
};

export function createLinearIphone(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderLinearScene(svg, current);
  };
  render();
  const controller = bindLinearScene(root, current);
  return {
    replay: controller.replay,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
  };
}
